import "./stats.css";

export interface StatItem {
  value: string;
  label: string;
}
export interface StatsProps {
  tone: "light" | "dark";
  items: StatItem[];
}

export function StatsRender({ tone, items }: StatsProps) {
  const list = items || [];
  const cols = Math.min(4, list.length || 1);
  return (
    <div className="p1-stats p1-block" data-tone={tone}>
      <div
        className="p1-stats__grid"
        style={{ gridTemplateColumns: `repeat(${cols}, minmax(0, 1fr))` }}
      >
        {list.map((it, i) => (
          <div key={i} className="p1-stats__item">
            <div className="p1-stats__value">{it.value}</div>
            <div className="p1-stats__label">{it.label}</div>
          </div>
        ))}
      </div>
    </div>
  );
}

import type { ComponentConfig } from "@puckeditor/core";
import { defineMeta } from '../define-meta';
import { StatsRender, type StatsProps, type StatItem } from "./stats";
export type { StatsProps, StatItem };

export const StatsBlock: ComponentConfig<StatsProps> = {
  fields: {
    tone: {
      type: "radio" as const,
      options: [
        { label: "Light", value: "light" },
        { label: "Dark", value: "dark" },
      ],
    },
    items: {
      type: "array" as const,
      arrayFields: {
        value: {
          type: "text" as const,
          contentEditable: true,
          visible: false,
          ai: { instructions: "The statistic value. E.g. 99.9% or 10k+." },
        },
        label: {
          type: "text" as const,
          contentEditable: true,
          visible: false,
          ai: { instructions: "Short label below the value. 2–4 words." },
        },
      },
      defaultItemProps: { value: "100%", label: "Metric" },
      getItemSummary: (item: StatItem) => item.value || "Stat",
    },
  },
  defaultProps: {
    tone: "light",
    items: [
      { value: "10k+", label: "Teams onboarded" },
      { value: "99.9%", label: "Uptime" },
      { value: "2M+", label: "Pages published" },
      { value: "4.9/5", label: "Customer rating" },
    ],
  },
  render: StatsRender,
};

export const meta = defineMeta({
  title: 'Stats',
  description: 'Horizontal grid of large value+label stat items in light or dark tone; use for key metrics or social-proof numbers.',
  categories: ["trust"],
  published: true,
});

.p1-stats[data-tone="light"] { background-color: var(--p1-surface-subtle); }
.p1-stats[data-tone="dark"] {
  background-color: var(--p1-surface-inverse);
  color: var(--p1-fg-inverse);
}

.p1-stats__grid {
  display: grid;
  gap: var(--p1-space-lg);
  grid-template-columns: 1fr;
  margin-inline: auto;
  max-inline-size: var(--p1-container-default);
}
@media (width >= 40rem) {
  .p1-stats__grid { grid-template-columns: repeat(2, 1fr); }
}
@media (width < 40rem) {
  .p1-stats__grid { grid-template-columns: 1fr !important; }
}

.p1-stats__item { text-align: center; }

.p1-stats__value {
  color: var(--p1-accent);
  font-size: var(--p1-text-3xl);
  font-weight: 800;
  letter-spacing: -0.02em;
}
@media (width >= 48rem) {
  .p1-stats__value { font-size: var(--p1-text-4xl); }
}
.p1-stats[data-tone="dark"] .p1-stats__value { color: var(--p1-warning); }

.p1-stats__label {
  color: var(--p1-fg-muted);
  font-size: var(--p1-text-sm);
  font-weight: var(--p1-weight-medium);
  margin-block-start: var(--p1-space-sm);
}
.p1-stats[data-tone="dark"] .p1-stats__label { color: var(--p1-fg-inverse-muted); }

